#!/usr/bin/env python3
"""Sum up 18 November 2026's world news in one image.

Draws a newspaper front page (1024 x 1024) with PIL and writes it to
/output/entry.png (or $MAKEFUN_OUTPUT_DIR/entry.png). No network, no
clock, no randomness: the same input always produces the same bytes.

The hero illustration is embedded below as a JPEG (base64, one line);
it was generated for this entry and is disclosed as an AI illustration
in the caption on the page itself.
"""

import base64
import io
import os

from PIL import Image, ImageDraw, ImageFont

W, H = 1024, 1024
MARGIN = 40
CONTENT_W = W - 2 * MARGIN
PAPER = (248, 244, 233)
INK = (26, 26, 26)
RED = (163, 31, 31)
GREY = (90, 86, 76)
BAND = (26, 26, 26)

HERO_JPEG_B64 = ""

FONT_DIRS = [
    "/usr/share/fonts/truetype/dejavu",
    "/usr/share/fonts/dejavu",
    "/usr/share/fonts/truetype",
]


def load_font(size, bold=False, serif=False):
    names = []
    if serif:
        names = ["DejaVuSerif-Bold.ttf"] if bold else ["DejaVuSerif.ttf"]
    else:
        names = ["DejaVuSans-Bold.ttf"] if bold else ["DejaVuSans.ttf"]
    for d in FONT_DIRS:
        for name in names:
            path = os.path.join(d, name)
            if os.path.exists(path):
                return ImageFont.truetype(path, size)
    return ImageFont.load_default(size=size)


def load_font_italic(size):
    for d in FONT_DIRS:
        for name in ("DejaVuSans-Oblique.ttf", "DejaVuSerif-Italic.ttf"):
            path = os.path.join(d, name)
            if os.path.exists(path):
                return ImageFont.truetype(path, size)
    return ImageFont.load_default(size=size)


def wrap(draw, text, font, max_width):
    words = text.split()
    lines, line = [], ""
    for word in words:
        trial = (line + " " + word).strip()
        if draw.textlength(trial, font=font) <= max_width:
            line = trial
        else:
            if line:
                lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def draw_centered(draw, y, lines, font, fill=INK, leading=None):
    if leading is None:
        leading = int(font.size * 1.18)
    for line in lines:
        w = draw.textlength(line, font=font)
        draw.text(((W - w) / 2, y), line, font=font, fill=fill)
        y += leading
    return y


def draw_rule(draw, y, weight=2):
    draw.line([(MARGIN, y), (W - MARGIN, y)], fill=INK, width=weight)
    return y + weight


def hero_image():
    raw = base64.b64decode(HERO_JPEG_B64)
    img = Image.open(io.BytesIO(raw)).convert("RGB")
    return img


def build_page():
    page = Image.new("RGB", (W, H), PAPER)
    draw = ImageDraw.Draw(page)

    # --- Masthead ---
    mast = load_font(58, bold=True, serif=True)
    draw_centered(draw, 14, ["THE WORLD IN ONE PAGE"], mast, leading=66)
    y = draw_rule(draw, 96, 3)

    # --- Dateline row ---
    date_font = load_font(15, bold=True)
    tag_font = load_font(15, bold=True)
    date = "Wednesday, 18 November 2026"
    tag = "WORLD EDITION"
    draw.text((MARGIN, y + 8), date, font=date_font, fill=INK)
    tw = draw.textlength(tag, font=tag_font)
    draw.text((W - MARGIN - tw, y + 8), tag, font=tag_font, fill=INK)
    y = draw_rule(draw, y + 34, 1)
    y = draw_rule(draw, y + 3, 2)

    # --- Main headline + subhead ---
    head_font = load_font(44, bold=True, serif=True)
    head_lines = wrap(draw, "SHENZHEN STAGE SET FOR RARE THREE-WAY SUMMIT",
                      head_font, CONTENT_W)
    y = draw_centered(draw, y + 12, head_lines, head_font, leading=52)
    sub_font = load_font(16)
    sub = ("Trump lands and is embraced by Xi at the airport; Xi and Putin meet "
           "for over two hours; the three exchange greetings at the APEC banquet "
           "ahead of Thursday's talks on Ukraine, Iran and nuclear arms.")
    sub_lines = wrap(draw, sub, sub_font, CONTENT_W)
    y = draw_centered(draw, y + 6, sub_lines, sub_font, fill=GREY, leading=21)

    # --- Hero illustration ---
    hero = hero_image()
    hero_h = 252
    hero = hero.resize((CONTENT_W, hero_h), Image.LANCZOS)
    hero_y = y + 10
    page.paste(hero, (MARGIN, hero_y))
    draw.rectangle([MARGIN, hero_y, W - MARGIN, hero_y + hero_h],
                   outline=INK, width=2)
    cap_font = load_font_italic(13)
    cap = ("AI illustration: the Shenzhen skyline and the flags of China, the "
           "United States and Russia outside the APEC summit venue, where the "
           "three leaders meet on Thursday.")
    cap_lines = wrap(draw, cap, cap_font, CONTENT_W)
    y = hero_y + hero_h + 8
    for line in cap_lines:
        draw.text((MARGIN, y), line, font=cap_font, fill=GREY)
        y += 17

    # --- Four story blocks, 2 x 2 ---
    stories = [
        ("SUMMIT  ·  SHENZHEN",
         "Xi and Putin meet, Trump arrives",
         "APEC opened in Shenzhen on Wednesday. Xi Jinping and Vladimir Putin "
         "talked for over two hours and both attacked Western protectionism and "
         "sanctions. Donald Trump landed and was embraced by Xi at the airport. "
         "The three exchanged greetings before the banquet. Their first "
         "trilateral meeting is set for Thursday, with Ukraine, Iran, nuclear "
         "arms, trade and AI on the agenda."),
        ("GULF  ·  WAR",
         "US and Iran trade strikes across the Gulf",
         "The United States struck an Iranian missile launch site on Qeshm "
         "Island on Tuesday, officials said, after attacks on US personnel and "
         "assets. Iran answered with drone attacks on a US air base in Kuwait "
         "\u2014 Kuwait said it engaged the drones and reported no hit \u2014 and "
         "on sites in Bahrain, where several attacks were intercepted before "
         "dawn. Shipping through the Strait of Hormuz stayed disrupted."),
        ("UKRAINE  ·  WAR",
         "Kerch Bridge road arch falls into the strait",
         "Ukrainian strikes on 16 and 17 November brought down the main road "
         "arch of the Kerch Bridge, the 19-km link between Russia and Crimea. "
         "Video verified by Reuters and the BBC showed the 227-metre arch in "
         "the water. Road traffic is suspended; rail has partly resumed. Two "
         "people were killed, the Russian-installed governor said. A third "
         "attack was reported on Wednesday, with no new damage confirmed."),
        ("GAZA  ·  TRUCE",
         "Truce monitor warns the ceasefire may collapse",
         "The US-backed Board of Peace warned the UN that the Gaza ceasefire "
         "could collapse, saying Israel and Hamas had both fallen short of "
         "their commitments and aid deliveries were still impeded. The WHO "
         "said 950,000 displaced Palestinians are living on flood-prone "
         "ground as Gaza enters a fourth winter of war."),
    ]
    kick_font = load_font(13, bold=True)
    story_head_font = load_font(19, bold=True, serif=True)
    body_font = load_font(13)
    col_w = (CONTENT_W - 24) // 2
    grid_y = y + 12
    row_h = 168
    for i, (kicker, headline, body) in enumerate(stories):
        col = i % 2
        row = i // 2
        x = MARGIN + col * (col_w + 24)
        top = grid_y + row * row_h
        draw.text((x, top), kicker, font=kick_font, fill=RED)
        head_lines = wrap(draw, headline, story_head_font, col_w)
        hy = top + 18
        for line in head_lines[:2]:
            draw.text((x, hy), line, font=story_head_font, fill=INK)
            hy += 23
        by = hy + 4
        body_lines = wrap(draw, body, body_font, col_w)
        for line in body_lines[:6]:
            draw.text((x, by), line, font=body_font, fill=INK)
            by += 17

    # --- ALSO strip ---
    strip_y = grid_y + 2 * row_h + 8
    draw.rectangle([0, strip_y, W, strip_y + 46], fill=BAND)
    also_font = load_font(13, bold=True)
    also_body = load_font(13)
    also = ("Peltola wins Alaska \u2014 Democrats take the Senate 56\u201344  \u2022  "
            "US loses measles-free status after 26 years  \u2022  Ebola in DR "
            "Congo passes 11,000 cases  \u2022  Voyager 1 reaches one light-day "
            "from Earth  \u2022  Quad leaders meet in Manila")
    also_lines = wrap(draw, also, also_body, CONTENT_W - 120)
    ay = strip_y + 6
    for line in also_lines[:2]:
        w = draw.textlength(line, font=also_body)
        draw.text(((W - w) / 2, ay), line, font=also_body, fill=(240, 236, 224))
        ay += 17
    label = "ALSO"
    lw = draw.textlength(label, font=also_font)
    draw.text((MARGIN, strip_y + 14), label, font=also_font, fill=(242, 201, 76))

    return page


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    page = build_page()
    page.save(os.path.join(out_dir, "entry.png"), format="PNG")


if __name__ == "__main__":
    main()
